// ─── Evaluate questions table text search result ─────────────────────────────
const allItems = $input.all();
let results;
if (allItems.length === 1 && Array.isArray(allItems[0].json)) {
  results = allItems[0].json;
} else {
  results = allItems.map(i => i.json).filter(r => r && typeof r === 'object' && !Array.isArray(r));
}

const hit = results.length > 0 && results[0]?.solution_md ? results[0] : null;

// Re-attach upstream context from Code: Prepare Text
const upstream = $('Code: Parse & Normalize1').first().json;

return [{
  json: {
    ...upstream,
    questionsHit:            !!hit,
    // Prefer solution_md; fall back to explanation_md if solution_md absent
    cachedSolutionMd:        hit?.solution_md      ?? hit?.explanation_md ?? null,
    questionsConfidence:     hit?.confidence_score ?? null,
    questionsSubject:        hit?.subject          ?? null,
    questionsChapter:        hit?.chapter          ?? null,
    questionsTopic:          hit?.topic            ?? null,
    questionsAnswerText:     hit?.answer_text      ?? null,
    questionsRowId:          hit?.id               ?? null,
    questionsDistance:       hit?.distance         ?? null,
  }
}];

const BOT_USERNAME = '@test_vertex_tele_bot';

const msg = $input.first().json.message;
if (!msg) throw new Error('[Router] No message object in Telegram payload.');

const entities = [
  ...(msg.entities         || []),
  ...(msg.caption_entities || []),
];
const fullText = msg.text || msg.caption || '';

// Private chats respond without requiring the bot tag
const isPrivateChat = msg.chat?.type === 'private';
const isBotTagged = entities.some(e => {
  if (e.type === 'mention') {
    const mentioned = fullText.substring(e.offset, e.offset + e.length);
    return mentioned.toLowerCase() === BOT_USERNAME.toLowerCase();
  }
  if (e.type === 'bot_command') return true;
  return false;
});

const hasPhoto    = Array.isArray(msg.photo) && msg.photo.length > 0;
const hasImageDoc = msg.document && typeof msg.document.mime_type === 'string' && msg.document.mime_type.startsWith('image/');
const hasText     = typeof msg.text    === 'string' && msg.text.trim().length    > 0;
const hasCaption  = typeof msg.caption === 'string' && msg.caption.trim().length > 0;

let messageType;
if ((hasPhoto || hasImageDoc) && hasCaption) {
  messageType = 'mixed';
} else if (hasPhoto || hasImageDoc) {
  messageType = 'image';
} else {
  messageType = 'text';
}

let photoFileId = null;
const imageSource = hasPhoto ? 'photo' : hasImageDoc ? 'document' : null;
if (hasPhoto)         photoFileId = msg.photo[msg.photo.length - 1].file_id;
else if (hasImageDoc) photoFileId = msg.document.file_id;

const questionText    = fullText.replace(/@\w+/g, '').trim();
const threadMessageId = msg.reply_to_message?.message_id ?? msg.message_id;

return [{
  json: {
    isBotTagged,
    messageType,
    chatId:          msg.chat.id,
    messageId:       msg.message_id,
    threadMessageId,
    fromUserId:      msg.from?.id       ?? null,
    fromUsername:    msg.from?.username ?? msg.from?.first_name ?? 'Unknown',
    questionText,
    imageSource,
    photoFileId,
    hasPhoto,
    hasImageDoc,
    hasText: hasText || hasCaption,
    timestamp: new Date(msg.date * 1000).toISOString(),
