const data = $input.first().json;
const rawText = data.cachedSolutionMd || '';

// ── Step 1: Unescape literal \n from DB storage ───────────────────────────────
let safeText = rawText.replace(/\\n/g, '\n');

// ── Step 2: Normalise named HTML entities → plain text or safe equivalents ────
safeText = safeText
  .replace(/&amp;/g, '\x00AMP\x00')
  .replace(/&lt;/g,  '\x00LT\x00')
  .replace(/&gt;/g,  '\x00GT\x00')
  .replace(/&quot;/g, '"')
  .replace(/&le;/g,  '≤')
  .replace(/&ge;/g,  '≥')
