  .replace(/&approx;/g, '≈')
  .replace(/&times;/g,  '×')
  .replace(/&divide;/g, '÷')
  .replace(/&plusmn;/g, '±')
  .replace(/&infin;/g,  '∞')
  .replace(/&alpha;/g,  'α')
  .replace(/&beta;/g,   'β')
  .replace(/&gamma;/g,  'γ')
  .replace(/&delta;/g,  'δ')
  .replace(/&pi;/g,     'π')
  .replace(/&omega;/g,  'ω')
  .replace(/&theta;/g,  'θ')
  .replace(/&phi;/g,    'φ')
  .replace(/&lambda;/g, 'λ')
  .replace(/&mu;/g,     'μ')
  .replace(/&sigma;/g,  'σ')
  .replace(/&Omega;/g,  'Ω')
  .replace(/&rArr;/g,   '⇒')
  .replace(/&rarr;/g,   '→')
  .replace(/&larr;/g,   '←')
  .replace(/&harr;/g,   '↔')
  .replace(/&sub;/g,    '⊂')
  .replace(/&sup;/g,    '⊃')
  .replace(/&cup;/g,    '∪')
  .replace(/&cap;/g,    '∩')
  .replace(/&isin;/g,   '∈')
  .replace(/&forall;/g, '∀')
  .replace(/&exist;/g,  '∃')
  .replace(/&sum;/g,    '∑')
  .replace(/&int;/g,    '∫')
  .replace(/&radic;/g,  '√')
  .replace(/&deg;/g,    '°')
  .replace(/&#(\d+);/g, (_, code) => String.fromCharCode(parseInt(code, 10)))
  .replace(/&#x([0-9a-fA-F]+);/g, (_, hex) => String.fromCharCode(parseInt(hex, 16)))
  .replace(/&[a-zA-Z][a-zA-Z0-9]*;/g, '');

// ── Step 3: Protect content inside <code>/<pre> ───────────────────────────────
safeText = safeText.replace(/<(code|pre)>([\s\S]*?)<\/\1>/g, (match, tag, inner) => {
  const restored = inner
    .replace(/\x00LT\x00/g, '<')
    .replace(/\x00GT\x00/g, '>')
    .replace(/\x00AMP\x00/g, '&');
  const safeInner = restored
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;');
  return `<${tag}>${safeInner}</${tag}>`;
});

// ── Step 4: Convert supported HTML → Telegram equivalents ────────────────────
safeText = safeText
  .replace(/<br\s*\/?>/gi, '\n')
  .replace(/<strong>([\s\S]*?)<\/strong>/gi, '<b>$1</b>')
  .replace(/<em>([\s\S]*?)<\/em>/gi, '<i>$1</i>')
  .replace(/<h[1-6][^>]*>([\s\S]*?)<\/h[1-6]>/gi, '<b>$1</b>\n')
  .replace(/<sub>([^<]*)<\/sub>/gi, '[$1]')
  .replace(/<sup>([^<]*)<\/sup>/gi, '^$1');

// ── Step 5: Strip unsupported tags (keep inner text) ─────────────────────────
safeText = safeText
  .replace(/<\/?(?:span|div|p|ul|ol|li|table|tr|td|th|hr|section|article|figure|img|svg|br)[^>]*>/gi, '')
  .replace(/\n{3,}/g, '\n\n')
  .trim();

// ── Step 6: Restore protected entities ───────────────────────────────────────
safeText = safeText
  .replace(/\x00LT\x00/g, '&lt;')
  .replace(/\x00GT\x00/g, '&gt;')
  .replace(/\x00AMP\x00/g, '&amp;');

// ── Step 7: Escape bare < > that are NOT valid Telegram tags ─────────────────
// Placeholder approach: protect valid tags, escape everything else, restore.
const TELEGRAM_TAG_RE = /<\/?(?:b|i|u|s|code|pre)>|<a(?:\s[^>]*)?>|<\/a>/g;
const tagBank = [];
safeText = safeText.replace(TELEGRAM_TAG_RE, (match) => {
  tagBank.push(match);
  return `\x01TAG${tagBank.length - 1}\x01`;
});
safeText = safeText.replace(/</g, '&lt;').replace(/>/g, '&gt;');
for (let i = 0; i < tagBank.length; i++) {
  safeText = safeText.replace(`\x01TAG${i}\x01`, tagBank[i]);
}

// ── Step 8: Tag-aware chunker (never splits inside an open HTML tag) ──────────
const CHUNK_SIZE = 3800;
const TRACKED_TAGS = ['b', 'i', 'u', 's', 'code', 'pre'];

function getOpenTags(text) {
  const stack = [];
  const tagRe = /<\/?([a-zA-Z]+)[^>]*>/g;
  let m;
  while ((m = tagRe.exec(text)) !== null) {
    const tag = m[1].toLowerCase();
    if (!TRACKED_TAGS.includes(tag)) continue;
    if (m[0].startsWith('</')) {
      const idx = stack.lastIndexOf(tag);
      if (idx !== -1) stack.splice(idx, 1);
    } else {
      stack.push(tag);
    }
  }
  return stack;
}

function closeTags(openTags) {
  return [...openTags].reverse().map(t => `</${t}>`).join('');
}

function reopenTags(openTags) {
  return openTags.map(t => `<${t}>`).join('');
}

const chunks = [];
let remaining = safeText;

while (remaining.length > 0) {
  if (remaining.length <= CHUNK_SIZE) {
    chunks.push({ json: { ...data, chunk: remaining.trim() } });
    break;
  }

  // Walk back from limit to find a safe whitespace split point
  let end = CHUNK_SIZE;
  while (end > 0 && remaining[end] !== '\n' && remaining[end] !== ' ') end--;
  if (end === 0) end = CHUNK_SIZE; // no whitespace found, force cut

  let slice = remaining.slice(0, end);
  const openTags = getOpenTags(slice);

  if (openTags.length > 0) {
    // Close open tags at end of this chunk, reopen at start of next
    slice = slice + closeTags(openTags);
    remaining = reopenTags(openTags) + remaining.slice(end);
  } else {
    remaining = remaining.slice(end);
  }

  chunks.push({ json: { ...data, chunk: slice.trim() } });
}

return chunks;

